@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700;800&display=swap');
:root{--ink:#f4ead6;--muted:#a9a18f;--red:#bd4a3c;--gold:#dcbb76;--night:#101813}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#101813;color:var(--ink);font-family:'DM Sans',sans-serif;overflow:hidden;touch-action:none}button{font:inherit;color:inherit}#game-shell{position:relative;width:100vw;height:100dvh;min-height:320px;overflow:hidden;background:#19241a;isolation:isolate}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 46%,transparent 35%,rgba(7,12,10,.23) 74%,rgba(7,12,10,.72) 130%);z-index:1}.screen{position:absolute;inset:0;z-index:4;display:grid;place-items:center}.screen[hidden],.topbar[hidden],.objective[hidden],.mobile-controls[hidden],.mobile-hint[hidden],.toast[hidden]{display:none}.title-screen{background:linear-gradient(90deg,rgba(9,15,12,.85) 0%,rgba(9,15,12,.55) 44%,rgba(9,15,12,.05) 100%)}.title-copy{width:min(510px,48vw);position:absolute;left:11%;top:50%;transform:translateY(-46%)}.eyebrow{font:500 10px 'DM Mono',monospace;letter-spacing:.24em;color:#d4bd87;display:flex;align-items:center;gap:12px;margin:0 0 22px}.eyebrow span{height:1px;width:28px;background:#a89262}.title-copy h1{font:800 clamp(44px,6.2vw,86px)/.87 'Playfair Display',serif;letter-spacing:-.055em;margin:0;color:#f5ead5;text-shadow:0 4px 30px #09110d}.title-copy h1 em{font-weight:600;color:#d3ad69}.intro{font-size:15px;letter-spacing:.025em;color:#c5c0b1;margin:24px 0 27px}.primary-btn{height:54px;padding:0 22px 0 25px;border:1px solid rgba(229,200,141,.52);background:#b44939;color:#fff4df;display:flex;align-items:center;justify-content:space-between;gap:34px;min-width:240px;cursor:pointer;letter-spacing:.12em;font-size:10px;font-weight:700;box-shadow:0 7px 24px #080d0a77;transition:transform .2s,background .2s}.primary-btn:hover{transform:translateY(-2px);background:#ce5745}.primary-btn b{font-size:17px;font-weight:400}.controls-note{font:9px 'DM Mono',monospace;letter-spacing:.08em;color:#969889;margin-top:24px}.controls-note i{color:#d2af70;font-style:normal;padding:0 4px}.title-seal{position:absolute;right:13%;top:50%;transform:translateY(-50%);width:clamp(170px,20vw,260px);aspect-ratio:1;border:1px solid #d5bd8770;border-radius:50%;display:grid;place-items:center;text-align:center;color:#e3c781;box-shadow:0 0 0 12px #d5bd8710,0 0 0 13px #d5bd8738,0 0 80px #d5bd8718;opacity:.86}.title-seal:before,.title-seal:after{content:'';position:absolute;inset:11px;border:1px solid #d5bd8745;border-radius:50%}.title-seal:after{inset:24px;border-style:dashed}.title-seal span{font-size:37px;position:absolute;top:24%;text-shadow:0 0 20px #d5bd87}.title-seal small{font:9px/1.7 'DM Mono',monospace;letter-spacing:.2em;margin-top:46px}.bottom-caption{position:absolute;bottom:30px;left:11%;font:9px 'DM Mono',monospace;letter-spacing:.15em;color:#969889}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:83px;padding:0 clamp(20px,5vw,72px);display:flex;align-items:center;justify-content:space-between;background:linear-gradient(#0b110ee6,transparent);pointer-events:none}.topbar>*{pointer-events:auto}.brand{display:flex;align-items:center;gap:10px;color:#e9dfc9}.brand-mark{font-size:24px;color:#d0ad6b}.brand b{display:block;font:600 10px 'DM Mono',monospace;letter-spacing:.16em}.brand small{font:8px 'DM Mono',monospace;letter-spacing:.28em;color:#a49c89}.run-stats{display:flex;align-items:center;gap:10px;font:12px 'DM Mono',monospace}.heart{font-size:15px;color:#d65b4a}.hearts{display:flex;gap:3px;color:#d65b4a;font-size:16px}.hearts .empty{color:#655c51}.divider{height:21px;width:1px;background:#d8c8a644;margin:0 5px}.soul-icon{font-size:20px;color:#d8ba79}.wave-pill{margin-left:17px;border:1px solid #dfcfaa42;padding:7px 12px;font-size:9px;letter-spacing:.13em;color:#dfcfaa}.icon-btn{width:37px;height:37px;background:#111a16a6;border:1px solid #dbc99855;color:#e5d7b6;font-size:15px;cursor:pointer}.objective{position:absolute;z-index:3;top:95px;left:50%;transform:translateX(-50%);padding:9px 16px;background:#111a16ad;border:1px solid #d8c28c2c;color:#e4d7b9;font:10px 'DM Mono',monospace;letter-spacing:.13em;white-space:nowrap}.objective-icon{color:#daba77;margin-right:8px}.panel{text-align:center;width:min(470px,90vw);padding:46px 38px;background:#111a16ed;border:1px solid #d2b97765;box-shadow:0 18px 80px #0009}.panel .eyebrow{justify-content:center}.panel h2{font:700 clamp(38px,6vw,63px)/1 'Playfair Display',serif;letter-spacing:-.04em;margin:0 0 25px}.panel>p:not(.eyebrow){color:#bdb5a2;font-size:14px;line-height:1.6;margin:-8px 0 24px}.panel .primary-btn{margin:0 auto}.text-btn{margin-top:20px;background:none;border:0;color:#a8a08d;font:9px 'DM Mono',monospace;letter-spacing:.15em;padding:12px;cursor:pointer}.toast{position:absolute;z-index:3;top:21%;left:50%;transform:translateX(-50%);padding:10px 18px;background:#111a16dd;border:1px solid #d8bc7955;color:#ebd29c;font:10px 'DM Mono',monospace;letter-spacing:.12em;white-space:nowrap}.mobile-controls,.mobile-hint{display:none}.screen-flash{position:absolute;inset:0;z-index:2;pointer-events:none;background:#d94f38;opacity:0;transition:opacity .1s}.screen-flash.hit{opacity:.13}
@media(max-width:700px){.title-copy{width:80%;left:9%;top:42%;transform:translateY(-40%)}.title-copy h1{font-size:clamp(46px,13vw,78px)}.intro{font-size:13px;margin:18px 0 22px}.title-seal{width:116px;right:8%;top:18%;transform:none;opacity:.55}.title-seal span{font-size:24px}.title-seal small{font-size:7px;margin-top:34px}.title-seal:after{inset:19px}.title-seal:before{inset:8px}.controls-note{font-size:8px;max-width:290px;line-height:1.8}.bottom-caption{left:9%;bottom:22px;font-size:7px}.topbar{height:68px;padding:0 16px}.brand{gap:7px}.brand-mark{font-size:19px}.brand b{font-size:8px}.brand small{font-size:6px}.run-stats{gap:6px;font-size:10px}.hearts{gap:1px;font-size:13px}.heart{font-size:12px}.wave-pill{margin-left:4px;padding:6px 7px;font-size:8px}.divider{margin:0 2px;height:16px}.soul-icon{font-size:16px}.icon-btn{width:32px;height:32px;font-size:13px}.objective{top:76px;font-size:9px}.mobile-controls{display:flex;position:absolute;z-index:3;bottom:max(22px,env(safe-area-inset-bottom));left:0;right:0;justify-content:space-between;align-items:end;padding:0 22px;pointer-events:none}.stick-zone{width:116px;height:116px;display:grid;place-items:center;pointer-events:auto;touch-action:none}.stick-ring{width:100px;height:100px;border-radius:50%;background:#10181267;border:1px solid #e8dfc251;display:grid;place-items:center;box-shadow:inset 0 0 0 8px #ffffff08}.stick-knob{width:42px;height:42px;border-radius:50%;background:#d6c6a755;border:1px solid #f0dfbd9e;box-shadow:0 4px 12px #0006;transform:translate(0,0)}.action-controls{display:flex;align-items:end;gap:13px;pointer-events:auto}.action-btn{border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;touch-action:none;box-shadow:0 5px 16px #0006}.action-btn span{font-size:21px;line-height:1}.action-btn small{font:7px 'DM Mono',monospace;letter-spacing:.1em}.attack-btn{width:70px;height:70px;background:#ad4338db;border:1px solid #e5b09c99;color:#fff0d4}.dodge-btn{width:55px;height:55px;background:#24332bd9;border:1px solid #ded0aa88;color:#e7d8b8;margin-bottom:4px}.mobile-hint{display:block;position:absolute;z-index:3;bottom:11px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#c6bda8aa;font:7px 'DM Mono',monospace;letter-spacing:.1em}.mobile-hint span{color:#d7b875;padding:0 4px}.title-screen~.mobile-controls{display:none!important}.panel{padding:36px 22px}.panel h2{font-size:42px}.panel .eyebrow{font-size:8px}}
@media(max-height:500px) and (max-width:900px){.title-copy{top:50%;width:60%}.title-copy h1{font-size:clamp(38px,8vh,64px)}.intro{margin:12px 0;font-size:12px}.title-seal{right:11%;width:125px}.primary-btn{height:45px}.controls-note{margin-top:12px}.mobile-controls{bottom:8px}.stick-zone{width:90px;height:90px}.stick-ring{width:78px;height:78px}.attack-btn{width:59px;height:59px}.dodge-btn{width:48px;height:48px}.topbar{height:58px}}

(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const shell = $('#game-shell');
  const ui = {title:$('#title-screen'),top:$('#topbar'),pause:$('#pause-screen'),end:$('#end-screen'),objective:$('#objective'),objectiveText:$('#objective-text'),hearts:$('#hearts'),souls:$('#souls'),wave:$('#wave'),toast:$('#toast'),mobile:$('#mobile-controls'),hint:$('#mobile-hint'),flash:$('#screen-flash')};
  let W=0,H=0,dpr=1,state='title',last=0,elapsed=0,attackHeld=false,attackCooldown=0,dashCooldown=0,toastTimer=0,shake=0;
  let player, enemies=[], particles=[], motes=[], wave=0, souls=0, keys={}, joystick={x:0,y:0,active:false}, isTouch=matchMedia('(pointer:coarse)').matches;
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), hypot=Math.hypot;
  function resize(){dpr=Math.min(devicePixelRatio||1,2);W=shell.clientWidth;H=shell.clientHeight;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
  window.addEventListener('resize',resize);resize();
  function showToast(text){ui.toast.textContent=text;ui.toast.hidden=false;toastTimer=1.5;}
  function playerStart(){return {x:W*.5,y:H*.58,r:17,hp:5,maxHp:5,faceX:0,faceY:-1,speed:210,invuln:0,dash:0,attackAnim:0,hitFlash:0};}
  function startGame(){state='play';ui.title.hidden=true;ui.end.hidden=true;ui.pause.hidden=true;ui.top.hidden=false;ui.objective.hidden=false;ui.mobile.hidden=false;ui.hint.hidden=!isTouch;player=playerStart();enemies=[];particles=[];souls=0;wave=0;elapsed=0;attackCooldown=0;dashCooldown=0;nextWave();updateHud();last=performance.now();}
  function nextWave(){wave++;const count=wave===1?4:wave===2?5:1;for(let i=0;i<count;i++){const a=(Math.PI*2*i/count)+rand(-.3,.3),rx=Math.min(W*.38,260),ry=Math.min(H*.31,200);enemies.push({x:W*.5+Math.cos(a)*rx,y:H*.48+Math.sin(a)*ry,r:wave===3?27:16,hp:wave===3?8:wave===2?2:1,maxHp:wave===3?8:wave===2?2:1,speed:wave===3?72:rand(48,68),damageClock:rand(.2,.8),flash:0,boss:wave===3,phase:rand(0,1),dead:false});}
    ui.wave.textContent=['I / III','II / III','III / III'][wave-1];ui.objectiveText.textContent=wave===3?'Defeat the Hollow Keeper':`Clear the grove · ${count} spirits`;showToast(wave===1?'THE WOODS HAVE WOKEN':wave===2?'THE SHADOWS GATHER':'THE KEEPER STIRS');}
  function updateHud(){ui.hearts.innerHTML=Array.from({length:player?player.maxHp:5},(_,i)=>`<span class="${player&&i>=player.hp?'empty':''}">♥</span>`).join('');ui.souls.textContent=String(souls).padStart(2,'0');}
  function endGame(won){state=won?'won':'lost';ui.end.hidden=false;ui.top.hidden=true;ui.objective.hidden=true;ui.mobile.hidden=true;ui.hint.hidden=true;$('#end-eyebrow').textContent=won?'THE OATH IS FULFILLED':'THE WOODS CLAIM ANOTHER';$('#end-title').textContent=won?'THE HOLLOW IS YOURS':'THE LAMB HAS FALLEN';$('#end-message').textContent=won?`The Hollow Keeper is still. You gathered ${souls} lost ${souls===1?'soul':'souls'} and brought the grove back to silence.`:'The path ends here, little lamb. The old shrine will remember your name.';}
  function togglePause(){if(state==='play'){state='pause';ui.pause.hidden=false;ui.mobile.hidden=true;ui.hint.hidden=true;attackHeld=false;}else if(state==='pause'){state='play';ui.pause.hidden=true;ui.mobile.hidden=false;ui.hint.hidden=!isTouch;last=performance.now();}}
  $('#start-btn').addEventListener('click',startGame);$('#again-btn').addEventListener('click',startGame);$('#pause-btn').addEventListener('click',togglePause);$('#resume-btn').addEventListener('click',togglePause);$('#restart-btn').addEventListener('click',startGame);
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=true;if(k==='escape'||k==='p'){if(state==='play'||state==='pause')togglePause();}if(k===' '||k==='enter')attackHeld=true;if((k==='shift'||k==='x')&&state==='play')dash();});
  window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;if(e.key===' ')attackHeld=false;});
  window.addEventListener('blur',()=>{keys={};attackHeld=false;if(state==='play')togglePause();});
  $('#attack-btn').addEventListener('pointerdown',e=>{e.preventDefault();attackHeld=true;$('#attack-btn').setPointerCapture(e.pointerId);});$('#attack-btn').addEventListener('pointerup',()=>attackHeld=false);$('#attack-btn').addEventListener('pointercancel',()=>attackHeld=false);
  $('#dodge-btn').addEventListener('pointerdown',e=>{e.preventDefault();dash();});
  const zone=$('#stick-zone'),knob=$('#stick-knob');let stickId=null;
  zone.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;zone.setPointerCapture(stickId);joystick.active=true;setStick(e);});
  zone.addEventListener('pointermove',e=>{if(e.pointerId===stickId)setStick(e);});
  function setStick(e){const r=zone.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,d=Math.min(34,hypot(dx,dy)),a=Math.atan2(dy,dx);joystick.x=Math.cos(a)*d/34;joystick.y=Math.sin(a)*d/34;knob.style.transform=`translate(${joystick.x*28}px,${joystick.y*28}px)`;}
  function clearStick(){stickId=null;joystick.active=false;joystick.x=joystick.y=0;knob.style.transform='translate(0,0)';}
  zone.addEventListener('pointerup',clearStick);zone.addEventListener('pointercancel',clearStick);
  function dash(){if(state!=='play'||dashCooldown>0)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joystick.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joystick.y,d=hypot(dx,dy);if(!d){dx=player.faceX;dy=player.faceY;d=1;}player.faceX=dx/d;player.faceY=dy/d;player.dash=.18;player.invuln=.48;dashCooldown=1.05;player.x=clamp(player.x+dx/d*105,40,W-40);player.y=clamp(player.y+dy/d*105,105,H-50);for(let i=0;i<8;i++)particles.push({x:player.x-rand(-12,12),y:player.y-rand(-12,12),vx:rand(-45,45),vy:rand(-50,30),life:rand(.15,.35),max:.35,color:'#d8bd83',size:rand(2,5)});}
  function attack(){if(attackCooldown>0)return;attackCooldown=.36;player.attackAnim=.22;let hit=false;let directionX=player.faceX,directionY=player.faceY;if(isTouch){let nearest=null,dist=150;for(const e of enemies){const d=hypot(e.x-player.x,e.y-player.y);if(d<dist){dist=d;nearest=e;}}if(nearest){directionX=(nearest.x-player.x)/dist;directionY=(nearest.y-player.y)/dist;player.faceX=directionX;player.faceY=directionY;}}
    for(const e of enemies){const dx=e.x-player.x,dy=e.y-player.y,d=hypot(dx,dy),dot=d?((dx/d)*directionX+(dy/d)*directionY):1;if(d<104+e.r&&dot>.12){e.hp--;e.flash=.14;hit=true;const n=d||1;e.x+=dx/n*18;e.y+=dy/n*18;for(let i=0;i<7;i++)particles.push({x:e.x,y:e.y,vx:rand(-90,90),vy:rand(-90,40),life:rand(.18,.4),max:.4,color:e.boss?'#bd5948':'#d6bc84',size:rand(2,5)});if(e.hp<=0){e.dead=true;souls++;for(let i=0;i<12;i++)particles.push({x:e.x,y:e.y,vx:rand(-80,80),vy:rand(-100,35),life:rand(.4,.8),max:.8,color:'#d4b975',size:rand(2,5)});}}}
    if(hit){shake=Math.max(shake,3);}
  }

function update(dt){elapsed+=dt;if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.hidden=true;}if(shake>0)shake=Math.max(0,shake-dt*18);if(!player)return;attackCooldown=Math.max(0,attackCooldown-dt);dashCooldown=Math.max(0,dashCooldown-dt);player.invuln=Math.max(0,player.invuln-dt);player.dash=Math.max(0,player.dash-dt);player.attackAnim=Math.max(0,player.attackAnim-dt);player.hitFlash=Math.max(0,player.hitFlash-dt);
  let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joystick.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joystick.y,d=hypot(dx,dy);if(d>0){dx/=Math.max(1,d);dy/=Math.max(1,d);player.faceX=dx;player.faceY=dy;player.x+=dx*player.speed*dt;player.y+=dy*player.speed*dt;}player.x=clamp(player.x,40,W-40);player.y=clamp(player.y,90,H-42);if(attackHeld)attack();
  for(const e of enemies){if(e.dead)continue;e.flash=Math.max(0,e.flash-dt);e.damageClock-=dt;const vx=player.x-e.x,vy=player.y-e.y,dist=hypot(vx,vy)||1;e.phase+=dt;if(e.boss&&dist<210&&e.damageClock<0){e.damageClock=-.55;e.windup=.55;e.chargeX=vx/dist;e.chargeY=vy/dist;}if(e.windup>0){e.windup-=dt;if(e.windup<=0)e.charge=.22;}if(e.charge>0){e.charge-=dt;e.x+=e.chargeX*e.speed*3.1*dt;e.y+=e.chargeY*e.speed*3.1*dt;}else if(dist>e.r+player.r+12){const sway=e.boss?0:Math.sin(e.phase*2.7)*.18;e.x+=((vx/dist)-vy/dist*sway)*e.speed*dt;e.y+=((vy/dist)+vx/dist*sway)*e.speed*dt;}if(dist<e.r+player.r+5&&e.damageClock<=0){e.damageClock=e.boss?1.1:1.35;if(player.invuln<=0){player.hp--;player.invuln=.9;player.hitFlash=.25;shake=8;ui.flash.classList.add('hit');setTimeout(()=>ui.flash.classList.remove('hit'),100);updateHud();if(player.hp<=0){endGame(false);return;}}}}
  enemies=enemies.filter(e=>!e.dead);if(enemies.length===0){if(wave<3){nextWave();if(player.hp<player.maxHp){player.hp++;updateHud();}}else{endGame(true);return;}}for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.15,dt);p.vy+=30*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);while(motes.length<36)motes.push({x:rand(0,W),y:rand(0,H),s:rand(.8,2),a:rand(.15,.55),speed:rand(4,17),phase:rand(0,7)});for(const m of motes){m.y-=m.speed*dt;m.phase+=dt;if(m.y<-5)m.y=H+5;}}
function roundedRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function drawBackground(){ctx.fillStyle='#19241b';ctx.fillRect(0,0,W,H);const g=ctx.createRadialGradient(W*.5,H*.48,30,W*.5,H*.5,Math.max(W,H)*.72);g.addColorStop(0,'#394735');g.addColorStop(.58,'#28382b');g.addColorStop(1,'#101913');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  // soft forest floor stipple
  for(let i=0;i<220;i++){const x=((i*137.5+37)%W),y=((i*83.3+13)%H),r=1+(i%3);ctx.globalAlpha=.05+(i%4)*.012;ctx.fillStyle=i%2?'#d4c487':'#08120c';ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
  // worn central clearing
  const cx=W*.5,cy=H*.49,rx=Math.min(W*.48,510),ry=Math.min(H*.42,360);ctx.beginPath();ctx.ellipse(cx,cy,rx,ry,0,0,Math.PI*2);ctx.fillStyle='#7d7958';ctx.globalAlpha=.22;ctx.fill();ctx.globalAlpha=1;ctx.beginPath();ctx.ellipse(cx,cy,rx*.97,ry*.96,0,0,Math.PI*2);ctx.fillStyle='#756f50';ctx.globalAlpha=.15;ctx.fill();ctx.globalAlpha=1;
  for(let i=0;i<90;i++){const a=i*2.399,r=Math.sqrt(i/90),x=cx+Math.cos(a)*rx*r,y=cy+Math.sin(a)*ry*r;ctx.globalAlpha=.1+(i%3)*.035;ctx.fillStyle=i%2?'#c9bd8c':'#18251b';ctx.beginPath();ctx.ellipse(x,y,rand(1,3),rand(1,2),a,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
  // old stones and broken outer pillars
  for(let i=0;i<14;i++){const a=i*Math.PI*2/14+.1,x=cx+Math.cos(a)*(rx*.92),y=cy+Math.sin(a)*(ry*.93);ctx.save();ctx.translate(x,y);ctx.rotate(a+.3);ctx.fillStyle='#7e8067';roundedRect(-10,-5,20,10,3);ctx.fill();ctx.strokeStyle='#a5a07a55';ctx.lineWidth=1;ctx.stroke();ctx.restore();}
  // trees framing the clearing
  const treePositions=[[.04,.12,.95],[.16,.06,.65],[.38,.03,.7],[.66,.08,.8],[.88,.06,.72],[.97,.2,.9],[.02,.47,.8],[.98,.52,.7],[.07,.83,.8],[.23,.95,.8],[.77,.94,.95],[.95,.83,.75]];
